/// <summary>
/// MPJ_28153 Interbranch Transfers	DCP 01/08/2022
/// </summary>
[ExtensionOf(formStr(InventTransferOrders))]
final class METInventTransferOrdersForm_Extension
{
    public InventParameters    metInventParameters    = InventParameters::find();
}

Method.Source:
    /// <summary>
    /// initialise extension
    /// </summary>
    public void init()
    {
        boolean openedFromRecord;

        next init();

        openedFromRecord =
        this.args()
        && this.args().record()
        && this.args().record().TableId == tableNum(WMSArrivalOverviewTmp);

        if (!openedFromRecord && METSecurityPolicyHelper::isRoleActiveForCurrentUser(
            roleStr(METInventLocationPolicyRole)) && !Global::isSystemAdministrator())
        {
            container warehouseCon =
                METUserSecurityWarehouseList::findMultipleWarehouseByUser();

            this.applyWarehouseFilter(warehouseCon);
            
        }

        this.METEnableFields();

    }

/// <summary>
/// enable extension fields
/// </summary>
public void METEnableFields()
{
    METInventTransferTableExt_ds.object(fieldNum(METInventTransferTableExt, AutoExtract)).allowEdit(false);
}

    /// <summary>
    /// Applies warehouse-based filtering to InventTransferTable datasource.
    /// </summary>
    /// <param name="_warehouseCon">
    /// Container containing alternating values; only warehouse IDs (even positions) are used.
    /// </param>
    /// <remarks>
    /// Converts warehouse list into query range and applies IN-clause filtering.
    /// </remarks>
    private void applyWarehouseFilter(container _warehouseCon)
    {
        QueryBuildDataSource qbds;
        QueryBuildRange      qbr;
        Set                  warehouseSet = new Set(Types::String);
        SetEnumerator        enumerator;
        InventLocationId     warehouseId;
        str                  rangeValue;
        int                  i;

        qbds = InventTransferTable_ds.queryBuildDataSource();

        // If no warehouses → block all data
        if (!conLen(_warehouseCon))
        {
            qbr = SysQuery::findOrCreateRange(
            qbds,
            fieldNum(InventTransferTable, RecId));

            qbr.value('0');
            InventTransferTable_ds.executeQuery();
            return;
        }

        // Collect unique warehouses
        for (i = 1; i <= conLen(_warehouseCon); i++)
        {
            warehouseId = conPeek(_warehouseCon, i);

            if (warehouseId)
            {
                warehouseSet.add(warehouseId);
            }
        }

        enumerator = warehouseSet.getEnumerator();

        while (enumerator.moveNext())
        {
            warehouseId = enumerator.current();

            if (rangeValue)
            {
                rangeValue += ' || ';
            }

            rangeValue += strFmt(
            '((%1 == "%2") || (%3 == "%2"))',
            fieldStr(InventTransferTable, InventLocationIdFrom),
            warehouseId,
            fieldStr(InventTransferTable, InventLocationIdTo));
        }

        if (rangeValue)
        {
            qbr = SysQuery::findOrCreateRange(
            qbds,
            fieldNum(InventTransferTable, RecId));

            qbr.value(strFmt('(%1)', rangeValue));
        }

        InventTransferTable_ds.executeQuery();
    }

    void enablePostButtons()
    {
        next enablePostButtons();

        boolean isTORestricted = false;
        
        if (InventTransferTable.InventLocationIdTo && METSecurityPolicyHelper::isRoleActiveForCurrentUser(roleStr(METInventLocationPolicyRole)))
        {
            METUserSecurityGroupList        securityGroupList;
            METUserSecurityWarehouseList    warehouseList;

            select firstonly RecId from warehouseList
                where warehouseList.InventLocationId == InventTransferTable.InventLocationIdTo
                   && warehouseList.Company == InventTransferTable.dataAreaId
                   && warehouseList.RestrictTOReceipts == NoYes::Yes
                exists join securityGroupList
                    where securityGroupList.UserSecurityGroupId == warehouseList.UserSecurityGroupId
                       && securityGroupList.UserId == curUserId();

            if (warehouseList.RecId)
            {
                isTORestricted = true;
            }
        }

        buttonInventTransferReceive.enabled(buttonInventTransferReceive.enabled() && !isTORestricted);
    }
